def prf(y_true, y_pred, labels=None):
    labels = labels or sorted(set(y_true) | set(y_pred))
    out = {}
    for c in labels:
        tp = sum(1 for t, p in zip(y_true, y_pred) if t == c and p == c)
        fp = sum(1 for t, p in zip(y_true, y_pred) if t != c and p == c)
        fn = sum(1 for t, p in zip(y_true, y_pred) if t == c and p != c)
        prec = tp / (tp + fp) if tp + fp else 0.0
        rec = tp / (tp + fn) if tp + fn else 0.0
        f1 = 2 * prec * rec / (prec + rec) if prec + rec else 0.0
        out[c] = (prec, rec, f1)
    macro = tuple(sum(v[i] for v in out.values()) / len(out) for i in range(3))
    return out, macro

def roc_auc(y, s):
    order = sorted(range(len(s)), key=lambda i: s[i])
    ranks = [0.0] * len(s)
    i = 0
    while i < len(order):
        j = i
        while j + 1 < len(order) and s[order[j + 1]] == s[order[i]]:
            j += 1
        r = (i + j) / 2 + 1            # средний ранг связки, 1-based
        for k in range(i, j + 1):
            ranks[order[k]] = r
        i = j + 1
    pos = [ranks[k] for k in range(len(y)) if y[k] == 1]
    n1, n0 = len(pos), len(y) - len(pos)
    if not n1 or not n0:
        raise ValueError("need both classes")
    return (sum(pos) - n1 * (n1 + 1) / 2) / (n1 * n0)

import numpy as np

def mha(X, Wq, Wk, Wv, Wo, h, causal=True):
    n, d = X.shape
    dk = d // h
    def split(M):                                  # (n, d) -> (h, n, dk)
        return M.reshape(n, h, dk).transpose(1, 0, 2)
    Qh, Kh, Vh = split(X @ Wq), split(X @ Wk), split(X @ Wv)
    outs = [attention(Qh[i], Kh[i], Vh[i], causal=causal)[0] for i in range(h)]
    O = np.stack(outs, axis=0).transpose(1, 0, 2).reshape(n, d)
    return O @ Wo

import math, random

def _softmax_list(z):
    m = max(z)
    e = [math.exp(v - m) for v in z]
    s = sum(e)
    return [v / s for v in e]

def sample(logits, temperature=1.0, top_k=None, top_p=None, rng=random):
    if temperature <= 0:
        return max(range(len(logits)), key=lambda i: logits[i])
    p = _softmax_list([v / temperature for v in logits])
    idx = sorted(range(len(p)), key=lambda i: -p[i])
    if top_k is not None:
        idx = idx[:top_k]
    if top_p is not None:
        keep, acc = [], 0.0
        for i in idx:
            keep.append(i)
            acc += p[i]
            if acc >= top_p:
                break
        idx = keep
    total = sum(p[i] for i in idx)
    r = rng.random() * total
    for i in idx:
        r -= p[i]
        if r <= 0:
            return i
    return idx[-1]

def _merge(syms, a, b):
    out, i = [], 0
    while i < len(syms):
        if i < len(syms) - 1 and syms[i] == a and syms[i + 1] == b:
            out.append(a + b)
            i += 2
        else:
            out.append(syms[i])
            i += 1
    return tuple(out)

def train_bpe(corpus, n_merges):
    words = {}
    for w in corpus.split():
        key = tuple(w) + ("</w>",)
        words[key] = words.get(key, 0) + 1
    merges = []
    for _ in range(n_merges):
        pairs = {}
        for syms, f in words.items():
            for pair in zip(syms, syms[1:]):
                pairs[pair] = pairs.get(pair, 0) + f
        if not pairs:
            break
        a, b = max(pairs, key=pairs.get)
        merges.append((a, b))
        words = { _merge(s, a, b): f for s, f in words.items() }
    return merges

def encode(word, merges):
    syms = tuple(word) + ("</w>",)
    for a, b in merges:
        syms = _merge(syms, a, b)
    return list(syms)

import math

def train(sents):
    uni, bi, vocab = {}, {}, set(["</s>"])
    for s in sents:
        toks = ["<s>"] + s.split() + ["</s>"]
        vocab.update(toks[1:])
        for a, b in zip(toks, toks[1:]):
            uni[a] = uni.get(a, 0) + 1
            bi[(a, b)] = bi.get((a, b), 0) + 1
    return uni, bi, len(vocab)

def perplexity(sents, uni, bi, V):
    lp, n = 0.0, 0
    for s in sents:
        toks = ["<s>"] + s.split() + ["</s>"]
        for a, b in zip(toks, toks[1:]):
            p = (bi.get((a, b), 0) + 1) / (uni.get(a, 0) + V)
            lp += math.log(p)
            n += 1
    return math.exp(-lp / n)

def beam_search(next_logprobs, bos, eos, k, max_len, alpha=0.0):
    beams = [([bos], 0.0)]
    done = []
    for _ in range(max_len):
        cand = []
        for seq, lp in beams:
            for tok, tlp in next_logprobs(seq):
                cand.append((seq + [tok], lp + tlp))
        beams = []
        for seq, lp in sorted(cand, key=lambda x: -x[1]):
            if seq[-1] == eos:
                done.append((seq, lp / len(seq) ** alpha))
            elif len(beams) < k:
                beams.append((seq, lp))
        if not beams:
            break
    done += [(s, lp / len(s) ** alpha) for s, lp in beams]
    return max(done, key=lambda x: x[1])[0]

import random

def kmeans(pts, k, iters=100, seed=0):
    rng = random.Random(seed)
    centers = [list(p) for p in rng.sample(list(pts), k)]
    assign = [-1] * len(pts)
    for _ in range(iters):
        changed = False
        for i, p in enumerate(pts):
            j = min(range(k),
                    key=lambda c: sum((a - b) ** 2 for a, b in zip(p, centers[c])))
            if j != assign[i]:
                assign[i] = j
                changed = True
        for c in range(k):
            mine = [pts[i] for i in range(len(pts)) if assign[i] == c]
            if mine:
                centers[c] = [sum(vals) / len(mine) for vals in zip(*mine)]
        if not changed:
            break
    return centers, assign
